    // ==================== 5. \u958B\u767C\u8005\u6A21\u5F0F ====================
    const DEV_MODE_KEY = 'catpaw-dev-mode';

    function isDevMode() {
        try {
            return localStorage.getItem(DEV_MODE_KEY) === '1';
        } catch (_) {
            return false;
        }
    }

    function setDevMode(enable) {
        try {
            if (enable) {
                localStorage.setItem(DEV_MODE_KEY, '1');
            } else {
                localStorage.removeItem(DEV_MODE_KEY);
            }
        } catch (_) {}
    }

    // \u66B4\u9732\u5168\u57DF API
    global.CatPaw = {
        theme: {
            set: setTheme,
            get: getPreferredTheme,
            toggle: toggleTheme,
            mountToggle: mountToggle,
            sync: syncThemeButtons,
        },
        escapeHtml,
        safeHtml,
        showToast,
        showConfirm,
        showAlert,
        downloadFile,
        attachDialogDismiss,
        isDevMode,
        setDevMode,
    };

    // \u65B9\u4FBF\u76F4\u63A5\u8ABF\u7528
    global.escapeHtml = escapeHtml;
    global.safeHtml = safeHtml;
    global.showToast = showToast;
    global.showConfirm = showConfirm;
    global.showAlert = showAlert;
    global.downloadFile = downloadFile;
    global.isDevMode = isDevMode;
    global.setDevMode = setDevMode;
