+ '<div class="wd-item">'
+ '  <div class="wd-item-body">'
+ '    <div class="wd-item-name">' + esc(s.name || s.address || s.id) + '</div>'
+ '    <div class="wd-item-addr">' + esc(displayAddr(s)) + (s.username ? ' \xB7 ' + esc(s.username) : '') + '</div>'
+ '  </div>'
+ '  <div class="wd-item-actions">'
+ '    <button class="btn btn-sm btn-tonal" type="button" data-action="test" data-id="' + esc(s.id) + '">\u6E2C\u8A66</button>'
+ '    <button class="btn btn-sm btn-outlined" type="button" data-action="edit" data-id="' + esc(s.id) + '">\u7DE8\u8F2F</button>'
+ '    <button class="btn btn-sm btn-danger-soft" type="button" data-action="delete" data-id="' + esc(s.id) + '">\u522A\u9664</button>'
